"""Generate a static, subpath-safe informational site. No backend or secrets."""
from pathlib import Path
from html import escape
import os
import re
from urllib.parse import quote
root = Path(__file__).resolve().parents[1] / 'site'
nav = [('Features','features.html'),('Integrations','integrations.html'),('Documentation','docs.html'),('Download','download.html')]
footer = [('Changelog','changelog.html'),('Privacy','privacy.html'),('Security','security.html'),('FAQ','faq.html'),('About & contact','about.html'),('Source','https://github.com/dotsoftwarelk/dotx-browser')]
def links(items): return ''.join(f'<a href="{u}">{escape(t)}</a>' for t,u in items)
def pages_base():
    """Base for GitHub Pages custom 404s; configurable for other static hosts."""
    explicit = os.environ.get('DOTX_PAGES_BASE_PATH')
    if explicit is not None:
        if not re.fullmatch(r'/(?:[A-Za-z0-9._~-]+/)*', explicit) or '..' in explicit:
            raise ValueError('DOTX_PAGES_BASE_PATH must be an absolute directory path')
        return explicit
    repo = os.environ.get('GITHUB_REPOSITORY', '')
    if '/' in repo:
        owner, name = repo.split('/', 1)
        return '/' if name.lower() == owner.lower() + '.github.io' else '/' + quote(name, safe='') + '/'
    return '/'

def render(title, description, body):
    base = f'<base href="{escape(pages_base(), quote=True)}">' if title == 'Page not found' else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8">{base}<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)} | DOTX Browser"><meta property="og:description" content="{escape(description,quote=True)}"><meta name="theme-color" content="#09111e"><title>{escape(title)} | DOTX Browser</title><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script defer src="assets/theme.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap topbar"><a href="index.html" class="brand"><img src="assets/mark.svg" alt=""><span>DOTX<small>BY DOTSOFTWARELK</small></span></a><nav class="nav" aria-label="Main navigation">{links(nav)}</nav><div class="theme-picker" hidden><label for="theme-picker">Theme</label><select id="theme-picker" aria-label="Color theme"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></div><details class="mobile-nav"><summary>Menu</summary><div>{links(nav+footer)}</div></details></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap footer-inner"><div><a href="index.html" class="brand"><img src="assets/mark.svg" alt=""><span>DOTX<small>BY DOTSOFTWARELK</small></span></a><p>A browser project in development. Built for a more focused workspace.</p></div><nav class="footer-links" aria-label="Footer navigation">{links(footer)}</nav></div></footer></body></html>'''
def page(title, intro, content):
    return f'<div class="wrap page"><div class="page-header"><span class="eyebrow">DOTX / {escape(title)}</span><h1>{escape(title)}</h1><p class="lead">{intro}</p></div><div class="content">{content}</div></div>'
home = '''<div class="wrap"><section class="hero"><div><span class="eyebrow">DOTX Browser · by dotsoftwarelk</span><h1>A clearer space<br>to get things done.</h1><p>A Windows browser project designed to bring everyday browsing and your essential tools into focus.</p><div class="actions"><a class="button primary" href="download.html">Get the development build &nbsp; →</a><a class="button" href="features.html">Explore DOTX</a></div><div class="fine">Development prototype · unsigned builds · not yet production-ready</div></div><figure class="product-visual"><img src="assets/browser-screenshot.png" width="1180" height="740" alt="Actual DOTX development browser window displaying a local sample page"><figcaption>Actual development browser, captured on Linux with a staged local sample page. Windows appearance may vary.</figcaption></figure></section></div><div class="band"><div class="wrap"><strong>Designed for your daily flow</strong><span>Browser essentials</span><span>Quick access to your tools</span><span>Transparent release status</span></div></div><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Thoughtful by design</span><h2>Less friction. More focus.</h2></div><a href="features.html">View all features →</a></div><div class="grid"><article class="card"><span class="num">01 / BROWSE</span><h3>One familiar starting point</h3><p>Navigate, search, and move between tabs in a streamlined desktop window.</p></article><article class="card"><span class="num">02 / RETURN</span><h3>Keep useful pages close</h3><p>Save bookmarks and revisit browsing history stored on your device.</p></article><article class="card"><span class="num">03 / WORKSPACE</span><h3>Get to your tools faster</h3><p>Quick-launch services or search public GitHub repositories and issues. Experimental GitHub sign-in requires configuration and has not been tested with a real account.</p></article></div></div></section><section class="section alt"><div class="wrap"><div class="callout"><div><span class="eyebrow">Built with clarity</span><h2>Know exactly where things stand.</h2><p>Read the current capabilities, limitations, and release status before you install.</p></div><a class="button primary" href="docs.html">Read the documentation →</a></div></div></section>'''
pages = {
'features.html': ('Features','A practical foundation for a more focused browsing experience.', '''<h2>Available in the development prototype</h2><p>Tabbed browsing with draggable and duplicate tabs, reopening recently closed tabs for the current session, address and search input, back, forward and reload, find in page and zoom controls. Save bookmarks in folders, import or export them as JSON, search and delete bookmark or history entries, select a search engine, and choose where to save downloads. Optional tab restoration stores page addresses locally. Choose light, dark, or system appearance for the browser chrome. The feature list describes current source; temporary build artifacts may come from an earlier snapshot.</p><h2>Workspace quick launch</h2><p>Open Dropbox, Google Docs, Google Drive, Linear, Notion, GitHub and Supabase websites in new tabs. These shortcuts are links, not account connections. Public GitHub repository and issue search also uses the GitHub REST API without authentication.</p><h2>Not yet implemented</h2><p>Experimental private windows use an off-the-record profile and do not save DOTX history or bookmarks; downloads remain on disk. Download retry and history, per-site permission settings, sync, other authenticated account connections, updates and a complete accessibility review remain future work. See the documentation before use.</p>'''),
'integrations.html': ('Integrations','A starting point for accessing the tools you already use.', '''<div class="notice"><p><strong>Current status:</strong> GitHub public repository and issue search uses the GitHub REST API without signing in. Other workspace destinations are website shortcuts. An experimental GitHub device sign-in requires an owner-registered app and has only been mock-tested. No account sync is implemented.</p></div>''' + ''.join((f'<h2>{name}</h2><p>Open the official website from the workspace. ' + ('Search public repositories and issues through the GitHub REST API without signing in. Queries and your IP address are sent to GitHub and rate limits apply. An experimental device sign-in verifies identity when configured; it has not been tested with a real account. Private repository and issue access is not implemented.' if name == 'GitHub' else 'Authentication and permissions are handled by that website. Native API access, connection status and setup are not yet implemented.') + '</p>') for name in ['Dropbox','Google Docs','Google Drive','Linear','Notion','GitHub','Supabase']) + '<p>These providers do not endorse DOTX. All names belong to their respective owners.</p>'),
'download.html': ('Download','Windows release information.', '''<div class="notice"><p><strong>No stable release is available.</strong> Unsigned development builds are experimental and not suitable for sensitive browsing.</p></div><h2>Temporary Windows x64 development build</h2><p>These are GitHub Actions artifacts, not GitHub Releases. A successful workflow checks the x64 executable, WebEngine helper, source smoke tests, packaged startup and silent install/uninstall. It does not prove interactive compatibility with Windows 10 and 11, upgrade safety or production readiness.</p><p id="build-status" role="status">Build availability requires JavaScript or the GitHub workflow link below.</p><p><a id="build-link" class="button primary" href="https://github.com/dotsoftwarelk/dotx-browser/actions/workflows/windows-development.yml" hidden>Open verified Windows build →</a></p><noscript><p>Enable JavaScript to check current artifact availability, or inspect the Windows workflow on GitHub.</p></noscript><p>On the run page, select <strong>DOTX-Windows-development-unsigned</strong>. GitHub sign-in is required to download artifacts; they expire. The archive contains an unsigned installer, a portable build and SHA-256 checksum files.</p><p><a href="https://github.com/dotsoftwarelk/dotx-browser/actions/workflows/windows-development.yml">Browse Windows workflow runs</a> · <a href="https://github.com/dotsoftwarelk/dotx-browser/releases">GitHub Releases</a></p><h2>For developers</h2><p>Source setup instructions are available in the <a href="docs.html">documentation</a>. Do not rely on unofficial installers.</p><script defer src="assets/download.js"></script>'''),
'changelog.html': ('Changelog','Changes and release history.', '<h2>Development prototype</h2><p>Initial source prototype. No public releases or verified version numbers have been established.</p>'),
'docs.html': ('Documentation','Get oriented with the current development prototype.', '''<h2>Setup</h2><p>Install Python and the dependencies in <code>requirements.txt</code>, then run <code>python -m dotx</code> from the <code>desktop</code> directory. This is a development workflow, not a verified Windows installer.</p><h2>Browser basics</h2><p>Use the address bar to enter a web address or search. Open tabs with the plus button; drag tabs to reorder them. Use the star to bookmark a page. Right-click a tab to duplicate it or reopen a recently closed tab. The Tools menu offers keyboard shortcuts, tab search, find and zoom. Settings offers opt-in tab restoration and requests deletion of cookies and HTTP cache; other site data may remain. The workspace buttons open provider websites. GitHub public search sends queries to GitHub without signing in.</p><h2>Data and troubleshooting</h2><p>History and bookmarks are stored locally. Browser engine data can also persist. If a site does not load, check your network and certificate settings; the prototype does not bypass certificate errors. Private windows are experimental; websites and network operators can still see activity, and downloads remain on disk. Advanced privacy controls are not yet available.</p><h2>Updates and integration setup</h2><p>No update system exists. Experimental GitHub device authorization requires owner configuration and has only been mock-tested; other service account connections are not implemented. Refer to the project source documentation for current limitations.</p>'''),
'privacy.html': ('Privacy','Understand what the prototype stores and sends.', '''<h2>Local data</h2><p>Browsing history, bookmarks and the search-engine selection are saved locally. If you enable tab restoration, page addresses are also stored locally and removed from settings when you turn it off. Bookmark JSON exports are unencrypted. Qt WebEngine may also store cookies, cache and other website data in its profile. Experimental private windows use a separate off-the-record profile and do not save DOTX history or bookmarks. Downloads remain on disk, and websites and network operators can still see activity. Complete clear-browsing-data controls are not yet available.</p><h2>External services</h2><p>Navigation and searches are sent to the websites and search provider you choose. Workspace links open third-party sites, which apply their own privacy policies. GitHub public searches send your query and IP address to GitHub. Experimental GitHub device sign-in sends authorization requests to GitHub; tokens stay in process memory and local disconnect does not revoke the grant. No DOTX cloud synchronization or persistent provider-token storage is implemented.</p><h2>This website</h2><p>The website stores your optional theme preference in browser local storage. The download page requests public build metadata directly from GitHub, which receives your network address. If GitHub is unavailable, the rest of the site still works.</p><h2>Account disconnection</h2><p>For GitHub, local disconnect removes the in-memory session but does not revoke the grant; revoke separately in GitHub settings. Sign out of other providers on their websites.</p>'''),
'security.html': ('Security','Transparent security information for a project in development.', '''<h2>Current status</h2><p>DOTX is a development prototype and has not undergone an independent security audit. Do not use it for sensitive browsing until its security and permissions have been reviewed and tested.</p><h2>Reporting</h2><p>A dedicated security contact has not yet been configured. The project owner must publish a private reporting method before public release. Do not post secrets or exploit details publicly.</p><h2>Release integrity</h2><p>No signed or verified Windows release exists yet. Do not rely on unofficial installers.</p>'''),
'faq.html': ('FAQ','Answers about the current project.', '''<h2>Is there an installer?</h2><p>A temporary unsigned development installer passed automated Windows CI checks; see the <a href="download.html">download page</a>. No stable release exists.</p><h2>Are my services connected?</h2><p>Workspace buttons open provider websites. GitHub public repository and issue search uses the public API without signing in. Experimental GitHub device sign-in requires configuration and has not been verified with a real account.</p><h2>Does it support private browsing or sync?</h2><p>Experimental private windows use an off-the-record profile and do not save DOTX history or bookmarks. They do not provide anonymity, and downloads remain on disk. Sync is not implemented.</p><h2>Does the app require Supabase?</h2><p>No. There is no Supabase backend in this prototype.</p><h2>Will it run on my PC?</h2><p>Windows compatibility and hardware performance have not yet been verified.</p>'''),
'about.html': ('About & contact','DOTX Browser is a project by dotsoftwarelk.', '''<h2>About</h2><p>DOTX is a browser project in development. This site documents its current prototype and does not represent a completed release.</p><h2>Contact</h2><p>A verified support or security contact has not yet been provided. The owner must add one before publication.</p>'''),
'404.html': ('Page not found','The page you requested could not be found.', '<p>Return to the <a href="index.html">DOTX home page</a> or explore the <a href="docs.html">documentation</a>.</p>'),
}
root.mkdir(exist_ok=True)
(root/'index.html').write_text(render('Home','DOTX Browser by dotsoftwarelk: a Windows browser project in development.',home), encoding='utf-8')
for filename,(title,intro,content) in pages.items():
    (root/filename).write_text(render(title, intro, page(title,intro,content)), encoding='utf-8')
(root/'robots.txt').write_text('User-agent: *\nAllow: /\n', encoding='utf-8')
print('Generated', len(pages)+1, 'HTML pages')
